import { test, expect } from '@playwright/test';

test.describe('Change Email Address with Confirmation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/user/profile');
  });

  test('should successfully change email address after confirmation', async ({ page }) => {
    // Verify current email is displayed
    const emailDisplay = page.getByText(/current email/);
    await expect(emailDisplay).toBeVisible();
    const currentEmail = page.getByText(/user@example.com/);
    await expect(currentEmail).toBeVisible();

    // Click edit email button
    const editButton = page.getByRole('button', { name: /edit email/i });
    await expect(editButton).toBeVisible();
    await editButton.click();

    // Fill in new email address
    const newEmailInput = page.getByLabel(/new email address/i);
    await expect(newEmailInput).toBeVisible();
    await newEmailInput.fill('new.email@example.com');

    // Click change email button
    const changeEmailButton = page.getByRole('button', { name: /change email/i });
    await expect(changeEmailButton).toBeVisible();
    await changeEmailButton.click();

    // Verify confirmation modal appears
    const confirmationModal = page.locator('[data-testid="confirmation-modal"]');
    await expect(confirmationModal).toBeVisible();

    // Click confirm button in modal
    const confirmButton = page.getByRole('button', { name: /confirm/i });
    await expect(confirmButton).toBeVisible();
    await confirmButton.click();

    // Verify success message
    const successMessage = page.getByText(/email address updated successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify new email is displayed
    const updatedEmail = page.getByText(/new.email@example.com/);
    await expect(updatedEmail).toBeVisible();
  });

  test('should prevent email change with invalid format and show error', async ({ page }) => {
    // Verify current email is displayed
    const emailDisplay = page.getByText(/current email/);
    await expect(emailDisplay).toBeVisible();

    // Click edit email button
    const editButton = page.getByRole('button', { name: /edit email/i });
    await expect(editButton).toBeVisible();
    await editButton.click();

    // Fill in invalid email address
    const newEmailInput = page.getByLabel(/new email address/i);
    await expect(newEmailInput).toBeVisible();
    await newEmailInput.fill('invalid-email');

    // Click change email button
    const changeEmailButton = page.getByRole('button', { name: /change email/i });
    await expect(changeEmailButton).toBeVisible();
    await changeEmailButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/invalid email format/i);
    await expect(errorMessage).toBeVisible();

    // Verify confirmation modal does not appear
    const confirmationModal = page.locator('[data-testid="confirmation-modal"]');
    await expect(confirmationModal).not.toBeVisible();

    // Verify email field still contains invalid input
    await expect(newEmailInput).toHaveValue('invalid-email');
  });
});
